@IsTest private class OwnedEnumCommentTest {
 @IsTest static void namesAndOrder() {
  System.assertEquals('Second',OwnedEnumCarrier.Phase.Second.name());
  System.assertEquals(1,OwnedEnumCarrier.Phase.Second.ordinal());
  List<OwnedEnumCarrier.Phase> items=OwnedEnumCarrier.Phase.values();
  System.assertEquals(3,items.size());
  System.assertEquals('First',items[0].name());
  System.assertEquals('Second',items[1].name());
  System.assertEquals('Third',items[2].name());
 }
 @IsTest static void plainNeighbor() {
  System.assertEquals('Single',OwnedEnumCarrier.Neighbor.Single.name());
  System.assertEquals(0,OwnedEnumCarrier.Neighbor.Single.ordinal());
  System.assertEquals(2,OwnedEnumCarrier.Neighbor.values().size());
 }
 @IsTest static void nullableValue() {
  OwnedEnumCarrier.Phase item=null;
  System.assertEquals(null,item);
 }
}

